function createReadRefresh ({ send, now = Date.now, minimumMs = 250 }) {
  let timer = null, lastRead = -Infinity, closed = false, latest
  return {
    request (identity = {}) {
      if (closed) return
      latest = identity
      if (timer) return
      timer = setTimeout(() => {
        timer = null
        if (closed) return
        lastRead = now()
        send(latest)
      }, Math.max(25, minimumMs - (now() - lastRead)))
      timer.unref?.()
    },
    close () { closed = true; clearTimeout(timer); timer = null }
  }
}

module.exports = { createReadRefresh }
